/// Index of a word by binary search. Input must already be lowercase.
pub fn index_of(word: &str) -> Option<usize> {
    WORDS.binary_search(&word).ok()
}

/// Resolve a four-letter (or longer) prefix to its unique word.
/// Every word has a distinct four-letter prefix, so this is unambiguous
/// and drives autocomplete in the restore dialog.
pub fn from_prefix(prefix: &str) -> Option<&'static str> {
    if prefix.len() < 4 {
        return None;
    }
    let start = WORDS.partition_point(|w| *w < prefix);
    WORDS.get(start).filter(|w| w.starts_with(prefix)).copied()
}
